"""扫描历史 jsonl：列出每行顶层事件与压缩相关事件、错误信息"""
import json
import sys

PATH = r"history_files/yt-2026-09-07_15.06.03_894_chat.jsonl"

def brief(v, n=300):
    s = v if isinstance(v, str) else json.dumps(v, ensure_ascii=False)
    s = s.replace("\n", "\\n")
    return s[:n] + ("…[len=%d]" % len(s) if len(s) > n else "")

with open(PATH, encoding="utf-8") as f:
    for i, line in enumerate(f, 1):
        line = line.strip()
        if not line:
            continue
        try:
            obj = json.loads(line)
        except Exception as exc:
            print(f"L{i} PARSE_ERR {exc}")
            continue
        ev = obj.get("event")
        if ev == "chat_round":
            print(f"L{i} chat_round q={brief(obj.get('question',''), 60)} status={obj.get('status')}")
            for j, e in enumerate(obj.get("events", [])):
                et = e.get("type", e.get("role", "?"))
                if "compaction" in str(et) or e.get("error") or "压缩" in str(e.get("content", ""))[:200]:
                    keys = {k: brief(e[k], 200) for k in e
                            if k in ("type", "timestamp", "scope", "phase", "error", "status",
                                     "compressed_rounds", "round_start", "round_end",
                                     "source_round_count", "summary_text", "compress_index")}
                    print(f"    e[{j}] {et} -> {keys}")
                    if e.get("error"):
                        print(f"        ERROR_DETAIL: {brief(e.get('error'), 800)}")
        else:
            print(f"L{i} event={ev} keys={list(obj.keys())[:8]}")
            for k in ("error", "detail", "message"):
                if obj.get(k):
                    print(f"    {k}: {brief(obj[k], 800)}")
","full_file_name":"tmp_scan_hist.py"}

