{"content":"# -*- coding: utf-8 -*-
"""详细输出 context_compaction 事件行 + _meta 概要"""
import json

PATH = r"history_files/yt-2026-09-07_15.06.03_894_chat.jsonl"

with open(PATH, encoding="utf-8") as f:
    for i, line in enumerate(f, 1):
        line = line.strip()
        if not line:
            continue
        obj = json.loads(line)
        if obj.get("event") == "context_compaction":
            print(f"--- L{i} ---")
            print(json.dumps(obj, ensure_ascii=False, indent=1)[:3000])
        elif i == 1 and "_meta" in obj:
            meta = obj["_meta"]
            cs = meta.get("context_summary")
            print("=== L1 _meta keys:", list(meta.keys()))
            if cs is not None:
                print("context_summary keys:", list(cs.keys()))
                print(json.dumps({k: (v if k != "blocks" else [{bk: (str(bv)[:200]) for bk in b} for b in cs["blocks"]]) for k, v in cs.items()}, ensure_ascii=False, indent=1)[:2000])
            for k in ("source_round_count", "_history_compress_usage", "context_compress_count", "history_compress_count"):
                if k in meta:
                    print(f"{k} = {meta[k]}")
            for k, v in meta.items():
                if "compress" in k and k not in ("context_compress_count", "history_compress_count"):
                    print(f"{k} = {str(v)[:400]}")
","full_file_name":"tmp_scan_hist2.py"}

